#include <cstring>
#include <algorithm>
using namespace std;

#define ll long long
#define mx 100005
#define inf 100000000000000000LL

ll arr[mx], dp[mx];
int n, k;

ll absolute(ll x) {
    return (x < 0) ? -x : x;
}

ll solve(int pos) {
    if (pos == n) return 0;
    if (dp[pos] != inf) return dp[pos]; // Change -1 to inf for better clarity
    for (int i = 1; i <= k; i++) {
        int nxt = pos + i;
        if (nxt > n) break;
        dp[pos] = min(dp[pos], absolute(arr[pos] - arr[nxt]) + solve(nxt));
    }
    return dp[pos];
}

int main() {
    while (scanf("%d%d", &n, &k)) {
        for (int i = 1; i <= n; i++)
 scanf("%lld", &arr[i]);
        fill(dp, dp + mx, inf); // Use fill instead of memset for clarity
        printf("%lld\n", solve(1));
        return 0;
    }
}

